#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 4096
#define MAX_KEYS 1024
#define MAX_STRING 65536

typedef enum {
    JSON_NULL, JSON_BOOLEAN, JSON_NUMBER, JSON_STRING,
    JSON_ARRAY, JSON_OBJECT
} TokenType;

typedef struct JsonValue {
    TokenType type;
    union {
        bool bool_val;
        double num_val;
        char *string_val;
        struct { char **keys; struct JsonValue **values; int count; } object;
        struct { struct JsonValue **items; int count; } array;
    } val;
} JsonValue;

static void skip_ws(const char **p) {
    while (**p && isspace(**p)) (*p)++;
}

static bool parse_string(JsonValue *v, const char **p) {
    if (**p != '"') return 0;
    (*p)++;
    v->val.string_val = malloc(MAX_STRING + 1);
    v->val.string_val[0] = '\0';
    int len = 0;
    while (**p && **p != '"' && len < MAX_STRING) {
        if (**p == '\\') {
            (*p)++;
            if (**p == 'n') v->val.string_val[len++] = '\n';
            else if (**p == 't') v->val.string_val[len++] = '\t';
            else if (**p == 'r') v->val.string_val[len++] = '\r';
            else if (**p == '\\') v->val.string_val[len++] = '\\';
            else if (**p == '"') v->val.string_val[len++] = '"';
            else if (**p == '/') v->val.string_val[len++] = '/';
            else if (**p == 'b') v->val.string_val[len++] = '\b';
            else if (**p == 'f') v->val.string_val[len++] = '\f';
            else if (**p == 'u') {
                (*p)++;
                char hex[4] = {0};
                for (int i = 0; i < 4; i++) {
                    if (**p && isxdigit(**p)) hex[i] = **p;
                    else break;
                    (*p)++;
                }
                v->val.string_val[len++] = (char)strtol(hex, NULL, 16);
            } else {
                v->val.string_val[len++] = **p;
            }
        } else {
            v->val.string_val[len++] = **p;
        }
        (*p)++;
    }
    v->val.string_val[len] = '\0';
    if (**p == '"') (*p)++;
    v->type = JSON_STRING;
    return 1;
}

static bool parse_number(JsonValue *v, const char **p) {
    long long num = 0;
    int neg = 0;
    if (**p == '-') { num = -1; (*p)++; neg = 1; }
    while (**p >= '0' && **p <= '9') {
        num = num * 10 + (**p - '0');
        (*p)++;
    }
    v->val.num_val = (double)num;
    v->type = JSON_NUMBER;
    return 1;
}

static bool parse_bool(JsonValue *v, const char **p) {
    if (strncmp(**p, "true", 4) == 0) { v->val.bool_val = 1; (*p) += 4; v->type = JSON_BOOLEAN; return 1; }
    if (strncmp(**p, "false", 5) == 0) { v->val.bool_val = 0; (*p) += 5; v->type = JSON_BOOLEAN; return 1; }
    return 0;
}

static bool parse_null(JsonValue *v, const char **p) {
    if (strncmp(**p, "null", 4) == 0) { v->type = JSON_NULL; (*p) += 4; return 1; }
    return 0;
}

static JsonValue *parse_json(const char *s, size_t len) {
    JsonValue *v = malloc(sizeof(JsonValue));
    const char *p = s;
    skip_ws(&p);
    if (p >= s + len) { free(v); return NULL; }
    char c = *p;
    if (c == '{') {
        v->type = JSON_OBJECT;
        v->val.keys = malloc(MAX_KEYS * sizeof(char*));
        v->val.values = malloc(MAX_KEYS * sizeof(JsonValue*));
        v->val.count = 0;
        p++; skip_ws(&p);
        while (p < s + len && *p != '}') {
            skip_ws(&p);
            if (p >= s + len) break;
            JsonValue *kv = parse_json(p, len - p);
            if (!kv) break;
            p = kv->val.string_val ? kv->val.string_val : (char*)kv;
            skip_ws(&p);
            if (*p == ':') { p++; skip_ws(&p); }
            JsonValue *val = parse_json(p, len - p);
            if (!val) break;
            if (v->val.count >= MAX_KEYS) { free(kv); free(val); free(v->val.keys); free(v->val.values); free(v); return NULL; }
            v->val.keys[v->val.count] = val->val.string_val;
            v->val.values[v->val.count] = val;
            v->val.count++;
            skip_ws(&p);
            if (*p == ',') { p++; skip_ws(&p); }
        }
        if (*p == '}') p++;
        if (v->val.count == 0) { free(v->val.keys); free(v->val.values); v->type = JSON_NULL; }
    } else if (c == '[') {
        v->type = JSON_ARRAY;
        v->val.items = malloc(MAX_KEYS * sizeof(JsonValue*));
        v->val.count = 0;
        p++; skip_ws(&p);
        while (p < s + len && *p != ']') {
            JsonValue *item = parse_json(p, len - p);
            if (!item) break;
            v->val.items[v->val.count++] = item;
            skip_ws(&p);
            if (*p == ',') { p++; skip_ws(&p); }
        }
        if (*p == ']') p++;
        if (v->val.count == 0) { free(v->val.items); v->type = JSON_NULL; }
    } else if (parse_bool(v, &p)) {
        skip_ws(&p);
    } else if (parse_null(v, &p)) {
        skip_ws(&p);
    } else if (parse_string(v, &p)) {
        skip_ws(&p);
    } else if (parse_number(v, &p)) {
        skip_ws(&p);
    } else {
        free(v);
        return NULL;
    }
    return v;
}

static void free_json(JsonValue *v) {
    if (!v) return;
    if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->val.count; i++) {
            free_json(v->val.values[i]);
            free(v->val.keys[i]);
        }
        free(v->val.keys);
        free(v->val.values);
    } else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->val.count; i++) {
            free_json(v->val.items[i]);
        }
        free(v->val.items);
    }
    if (v->type == JSON_STRING) free(v->val.string_val);
    free(v);
}

static int cmp_keys(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

static void sort_keys(JsonValue *v) {
    if (v->type == JSON_OBJECT) {
        qsort(v->val.keys, v->val.count, sizeof(char *), cmp_keys);
        JsonValue *temp = malloc(sizeof(JsonValue) * v->val.count);
        for (int i = 0; i < v->val.count; i++) {
