        def deep_merge(a, b):
            if isinstance(a, dict) and isinstance(b, dict):
                result = dict(a)
                for key, value in b.items():
                    if key in result:
                        if isinstance(result[key], dict) and isinstance(value, dict):
                            result[key] = deep_merge(result[key], value)
                        elif isinstance(result[key], list) and isinstance(value, list):
                            result[key] = deep_list_merge(result[key], value)
                        else:
                            result[key] = value
                    else:
                        result[key] = value
                return result
            elif isinstance(a, list) and isinstance(b, list):
                return deep_list_merge(a, b)
            else:
                return b

        def deep_list_merge(a, b):
            # A first, then B. Remove duplicates.
            # Use a list for seen to handle unhashable types (though primitives are hashable)
            # However, checking 'in' on a list of dicts is slow O(N).
            # Given the constraints and typical usage, let's assume primitives or simple equality.
            # To be safe and efficient enough, we check equality.
            seen = []
            result = []
            # Add items from A
            for item in a:
                if item not in seen:
                    seen.append(item)
                    result.append(item)
            # Add items from B
            for item in b:
                if item not in seen:
                    seen.append(item)
                    result.append(item)
            return result

