            highest_paid_name = name.clone();
        }
    }

    // Count employees by department
    let mut dept_counts: HashMap<String, u64> = HashMap::new();
    for (emp_id, name, dept, salary, start_date, rating) in &employees {
        *dept_counts.entry(dept.clone()).or_default() += 1;
    }

    // Total budget
    let total_budget: u64 = employees.iter().map(|(_, _, _, salary, _, _)| salary).sum();

    // Format output
    println!("=== Salary Report ===");
