    let mut num_str = s.chars().rev().collect::<Vec<char>>();
    for (i, ch) in num_str.iter().enumerate() {
        if i > 0 && i % 3 == 0 {
            result.push(',');
        }
        result.push(*ch);
    }
    num_str.reverse();
    result
}

