fn merge_json(a: &str, b: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut result = BTreeMap::new();
    parse_json_object(a, &mut result)?;
    parse_json_object(b, &mut result)?;
    Ok(serialize_json(&result))
}

fn parse_json_object(json: &str, target: &mut BTreeMap<String, String>) -> Result<(), Box<dyn std::error::Error>> {
    let mut chars = json.chars().peekable();
    let mut obj_start = None;
    let mut current_key = String::new();
    let mut current_value = String::new();
    let mut in_array = false;
    let mut array_start = None;
    let mut array_len = 0;
    let mut depth = 0;
    let mut in_string = false;
    let mut string_content = String::new();

    while let Some(c) = chars.next() {
        if in_string {
            if c == '\\' {
                string_content.push(c);
            } else if c == '"' {
                in_string = false;
                let trimmed = string_content.trim();
                if let Some(key) = trimmed.strip_prefix('"') {
                    if let Some(val) = trimmed.strip_suffix('"') {
                        current_value = val.to_string();
                    }
                }
                string_content.clear();
            } else {
                string_content.push(c);
            }
        } else {
            if c == '{' {
                if depth == 0 {
                    obj_start = Some((current_key.clone(), current_value.clone()));
                    current_key.clear();
                    current_value.clear();
                }
                depth += 1;
                if depth == 1 {
                    target.insert(current_key, current_value);
                }
            } else if c == '}' {
                depth -= 1;
                if depth == 0 {
                    current_key = String::new();
                    current_value = String::new();
                }
            } else if c == '[' {
                if depth == 0 {
                    obj_start = Some((current_key.clone(), current_value.clone()));
                    current_key.clear();
                    current_value.clear();
                }
                depth += 1;
            } else if c == ']' {
                depth -= 1;
            } else if c == ':' {
                if depth == 1 {
                    if let Some((key, value)) = obj_start {
                        target.insert(key, value);
                    }
                    current_key.clear();
                    current_value = String::new();
                }
            } else if c == ',' {
                current_key.clear();
                current_value = String::new();
            } else if c == '"' {
                in_string = !in_string;
            } else {
                if in_string {
                    string_content.push(c);
                } else {
                    current_value.push(c);
                }
            }
        }
    }

    Ok(())
}

fn serialize_json(obj: &BTreeMap<String, String>) -> String {
    let mut lines = Vec::new();
    lines.push("{");

    let mut keys: Vec<String> = obj.keys().cloned().collect();
    keys.sort();

    for (i, key) in keys.iter().enumerate() {
        let value = obj.get(key).unwrap();
        let escaped = value.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r").replace('\t', "\\t");
        let line = format!("  \"{}\": \"{}\"", key, escaped);
        lines.push(line);
        if i < keys.len() - 1 {
            lines.push(",");
        }
    }

    lines.push("}");
    lines.join("\n")
}

