    let mut chars = json.chars().peekable();
    let mut depth = 0;
    let mut current_key = String::new();
    let mut current_value = String::new();
    let mut in_string = false;
    let mut string_content = String::new();

    while let Some(c) = chars.next() {
        if in_string {
            if c == '\\' {
                string_content.push(c);
            } else if c == '"' {
                in_string = false;
                let trimmed = string_content.trim();
                if let Some(key) = trimmed.strip_prefix('"') {
                    if let Some(val) = trimmed.strip_suffix('"') {
                        current_value = val.to_string();
                    }
                }
                string_content.clear();
            } else {
                string_content.push(c);
            }
        } else {
            if c == '{' {
                depth += 1;
            } else if c == '}' {
                depth -= 1;
                if depth == 0 {
                    current_key = String::new();
                    current_value = String::new();
                }
            } else if c == ':' {
                if depth == 1 {
                    if !current_key.is_empty() {
                        result.insert(current_key.clone(), current_value);
                    }
                    current_key = String::new();
                    current_value = String::new();
                }
            } else if c == ',' {
                current_key = String::new();
                current_value = String::new();
            } else if c == '"' {
                in_string = !in_string;
            } else {
                if in_string {
                    string_content.push(c);
                } else {
                    current_value.push(c);
                }
            }
        }
    }

    for (key, value) in result {
        println!("{}: {}", key, value);
    }

    Ok(result)
}

fn serialize_json(obj: &BTreeMap<String, String>) -> String {
    let mut lines = Vec::new();
    lines.push("{");

    for (key, value) in obj {
        let escaped = value.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r").replace('\t', "\\t");
        let line = format!("  \"{}\": \"{}\"", key, escaped);
        lines.push(line);
    }

    lines.push("}");
    lines.join("\n")
}

