    let obj_b: serde_json::Value = serde_json::from_str(b).expect("Failed to parse config_b.json");
    merge_objects(&obj_a, &obj_b)
}

fn merge_objects(a: &serde_json::Value, b: &serde_json::Value) -> serde_json::Value {
    match (a, b) {
        (serde_json::Value::Object(a_map), serde_json::Value::Object(b_map)) => {
            let mut result = BTreeMap::new();
            for (key, value) in a_map {
                result.insert(key.clone(), value.clone());
            }
            for (key, value) in b_map {
                if let Some(existing) = result.get_mut(&key) {
                    if let (serde_json::Value::Array(a_arr), serde_json::Value::Array(b_arr)) = (existing, value) {
                        *existing = merge_arrays(a_arr, b_arr);
                    } else if let (serde_json::Value::Object(a_map), serde_json::Value::Object(b_map)) = (existing, value) {
                        *existing = merge_objects(a_map, b_map);
                    } else {
                        *existing = value.clone();
                    }
                } else {
                    result.insert(key, value.clone());
                }
            }
            serde_json::Value::Object(result)
        }
        (serde_json::Value::Array(a_arr), serde_json::Value::Array(b_arr)) => {
            let mut result = Vec::new();
            for item in a_arr {
                result.push(item.clone());
            }
            for item in b_arr {
                let mut found = false;
                for existing in &mut result {
                    if existing == item {
                        found = true;
                        break;
                    }
                }
                if !found {
                    result.push(item.clone());
                }
            }
            serde_json::Value::Array(result)
        }
        (_, _) => b.clone(),
    }
}

