use std::collections::BTreeMap;
use std::fs;
use std::fmt;

enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

impl Clone for JsonValue {
    fn clone(&self) -> Self {
        match self {
            JsonValue::Null => JsonValue::Null,
            JsonValue::Bool(b) => JsonValue::Bool(*b),
            JsonValue::Number(n) => JsonValue::Number(*n),
            JsonValue::String(s) => JsonValue::String(s.clone()),
            JsonValue::Array(a) => JsonValue::Array(a.clone()),
            JsonValue::Object(o) => JsonValue::Object(o.clone()),
        }
    }
}

impl PartialEq for JsonValue {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (JsonValue::Null, JsonValue::Null) => true,
            (JsonValue::Bool(a), JsonValue::Bool(b)) => a == b,
            (JsonValue::Number(a), JsonValue::Number(b)) => a == b,
            (JsonValue::String(a), JsonValue::String(b)) => a == b,
            (JsonValue::Array(a), JsonValue::Array(b)) => a == b,
            (JsonValue::Object(a), JsonValue::Object(b)) => a == b,
            _ => false,
        }
    }
}

impl Eq for JsonValue {}

fn merge_json_objects(a: &JsonValue, b: &JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(a_map), JsonValue::Object(b_map)) => {
            let mut result = a_map.clone();
            for (k, val_b) in b_map {
                if let Some(val_a) = result.get_mut(&k) {
                    *val_a = merge_json_objects(val_a, val_b);
                } else {
                    result.insert(k.clone(), val_b.clone());
                }
            }
            JsonValue::Object(result)
        }
        (JsonValue::Array(a_arr), JsonValue::Array(b_arr)) => {
            let mut result = a_arr.clone();
            for val_b in b_arr {
                let mut found = false;
                for val_a in &result {
                    if val_a == val_b {
                        found = true;
                        break;
                    }
                }
                if !found {
                    result.push(val_b.clone());
                }
            }
            JsonValue::Array(result)
        }
        _ => b.clone(),
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let chars = s.chars().peekable();
    let mut pos = 0;

    fn parse_number(s: &str, pos: &mut usize) -> Result<JsonValue, String> {
        let start = *pos;
        if s.as_bytes()[*pos] == b'-' {
            *pos += 1;
        }
        if s.as_bytes()[*pos] == b'0' {
            *pos += 1;
            if *pos < s.len() && s.as_bytes()[*pos] == b'.' {
                *pos += 1;
            }
            return Ok(JsonValue::Number(0.0));
        }
        while *pos < s.len() {
            let c = s.as_bytes()[*pos];
            if c == b'.' || c == b'+' || c == b'e' || c == b'E' || c >= b'0' && c <= b'9' {
                *pos += 1;
            } else {
                break;
            }
        }
        let num_str = &s[start..*pos];
        num_str.parse::<f64>().map(JsonValue::Number).map_err(|e| e.to_string())
    }

    fn parse_string(s: &str, pos: &mut usize) -> Result<JsonValue, String> {
        if *pos >= s.len() || s.as_bytes()[*pos] != b'"' {
            return Err("Expected string start".to_string());
        }
        *pos += 1;
        let mut result = String::new();
        while *pos < s.len() {
            let c = s.as_bytes()[*pos];
            if c == b'"' {
                *pos += 1;
                return Ok(JsonValue::String(result));
            } else if c == b'\\' {
                *pos += 1;
                if *pos >= s.len() {
                    return Err("Unexpected end of string".to_string());
                }
                let escape = s.as_bytes()[*pos];
                match escape {
                    b'"' | b'\\' | b'/' | b'b' | b'n' | b'r' | b't' => {
                        result.push(*escape as char);
                    }
                    b'u' => {
                        if *pos + 4 > s.len() {
                            return Err("Invalid unicode escape".to_string());
                        }
                        let hex = &s[*pos + 1..*pos + 5];
                        let code = u32::from_str_radix(hex, 16)
                            .map_err(|_| "Invalid unicode escape".to_string())?;
                        result.push(char::from_u32(code).unwrap_or('?'));
                        *pos += 4;
                    }
                    _ => {
                        return Err(format!("Invalid escape sequence: {:?}", escape as char));
                    }
                }
                *pos += 1;
            } else {
                result.push(c as char);
                *pos += 1;
            }
        }
        Err("Unexpected end of string".to_string())
    }

    fn parse_value(s: &str, pos: &mut usize) -> Result<JsonValue, String> {
        // Skip whitespace
        while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
            *pos += 1;
        }
        if *pos >= s.len() {
            return Err("Unexpected end of input".to_string());
        }

        let c = s.as_bytes()[*pos];
        match c {
            b'{' => {
                *pos += 1;
                let mut obj = BTreeMap::new();
                loop {
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                    if *pos >= s.len() || s.as_bytes()[*pos] == b'}' {
                        break;
                    }
                    let key_str = parse_string(s, pos)?;
                    let key: String = key_str.clone();
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                    if *pos >= s.len() || s.as_bytes()[*pos] != b':' {
                        return Err("Expected colon".to_string());
                    }
                    *pos += 1;
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                    let val = parse_value(s, pos)?;
                    obj.insert(key, val);
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                    if *pos >= s.len() || s.as_bytes()[*pos] == b'}' {
                        break;
                    }
                    if *pos >= s.len() || s.as_bytes()[*pos] != b',' {
                        return Err("Expected comma".to_string());
                    }
                    *pos += 1;
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                }
                Ok(JsonValue::Object(obj))
            }
            b'[' => {
                *pos += 1;
                let mut arr = Vec::new();
                loop {
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                    if *pos >= s.len() || s.as_bytes()[*pos] == b']' {
                        break;
                    }
                    let val = parse_value(s, pos)?;
                    arr.push(val);
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                    if *pos >= s.len() || s.as_bytes()[*pos] == b']' {
                        break;
                    }
                    if *pos >= s.len() || s.as_bytes()[*pos] != b',' {
                        return Err("Expected comma".to_string());
                    }
                    *pos += 1;
                    while *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                        *pos += 1;
                    }
                }
                Ok(JsonValue::Array(arr))
            }
            b't' => {
                *pos += 1;
                if *pos < s.len() && s.as_bytes()[*pos] == b'r' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b'u' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b'e' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b'l' {
                    *pos += 1;
                }
                Ok(JsonValue::Null)
            }
            b't' | b'f' | b't' | b'f' => {
                let val = if c == b't' { true } else { false };
                *pos += 1;
                if *pos < s.len() && s.as_bytes()[*pos] == b'r' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b'u' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b's' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b'e' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b' ' {
                    *pos += 1;
                }
                Ok(JsonValue::Bool(val))
            }
            b'n' => {
                *pos += 1;
                if *pos < s.len() && s.as_bytes()[*pos] == b'u' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b'l' {
                    *pos += 1;
                }
                if *pos < s.len() && s.as_bytes()[*pos] == b'l' {
                    *pos += 1;
                }
                Ok(JsonValue::Null)
            }
            c if c >= b'0' && c <= b'9' => {
                *pos += 1;
                parse_number(s, pos)
            }
            b'-' => {
                *pos += 1;
                parse_number(s, pos)
            }
            b'"' => {
                *pos += 1;
                parse_string(s, pos)
            }
            _ => Err(format!("Unexpected character: {:?}", c as char)),
        }
    }

    let result = parse_value(s, &mut pos)?;
    Ok(result)
}

fn serialize_json(obj: &JsonValue) -> String {
    fn serialize_val(val: &JsonValue, buf: &mut String) {
        match val {
            JsonValue::Null => buf.push_str("null"),
            JsonValue::Bool(b) => buf.push_str(if *b { "true" } else { "false" }),
            JsonValue::Number(n) => {
                if n.fract() == 0.0 {
                    buf.push_str(&n.to_string());
                } else {
                    buf.push_str(&n.to_string());
                }
            }
            JsonValue::String(s) => {
                buf.push('"');
                for c in s.chars() {
                    match c {
                        '"' => buf.push_str("\\\""),
                        '\\' => buf.push_str("\\\\"),
                        '\n' => buf.push_str("\\n"),
                        '\r' => buf.push_str("\\r"),
                        '\t' => buf.push_str("\\t"),
                        _ => buf.push(c),
                    }
                }
                buf.push('"');
            }
            JsonValue::Array(arr) => {
                buf.push('[');
                for (i, item) in arr.iter().enumerate() {
                    if i > 0 {
                        buf.push(',');
                    }
                    buf.push(' ');
                    serialize_val(item, buf);
                }
                buf.push(']');
            }
            JsonValue::Object(obj) => {
                buf.push('{');
                for (i, (key, val)) in obj.iter().enumerate() {
                    if i > 0 {
                        buf.push(',');
                    }
                    buf.push(' ');
                    buf.push('"');
                    for c in key.chars() {
                        match c {
                            '"' => buf.push_str("\\\""),
                            '\\' => buf.push_str("\\\\"),
                            _ => buf.push(c),
                        }
                    }
                    buf.push('"');
                    buf.push(':');
                    buf.push(' ');
                    serialize_val(val, buf);
                }
                buf.push('}');
            }
        }
    }

    let mut result = String::new();
    serialize_val(obj, &mut result);
    result
}

