import * as fs from 'fs';

const filePath = '/tmp/…/app.log';

async function main() {
  try {
    const content = await fs.promises.readFile(filePath, 'utf-8');
    const lines = content.split('\n');

    const levelCounts = new Map<string, number>();
    const componentErrorCounts = new Map<string, number>();
    const errorMessages = new Set<string>();
    const hourCounts = new Map<string, number>();

    for (const line of lines) {
      if (!line.trim()) continue;

      // Regex: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
      const match = line.match(/^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \((\w+)\) - (.*)$/);
      if (!match) continue;

      const [, timestamp, level, component, message] = match;
      const [hour] = timestamp.split(' ')[1].split(':');
      const hourStr = `${hour}:00`;

      // Count Levels
      levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

      // Count Hours
      hourCounts.set(hourStr, (hourCounts.get(hourStr) || 0) + 1);

      // Track Errors
      if (level === 'ERROR') {
        componentErrorCounts.set(component, (componentErrorCounts.get(component) || 0) + 1);
        // Message is everything after ' - '
        errorMessages.add(message.trim());
      }
    }

    // Output
    console.log('=== Log Analysis ===');
    console.log('');

    // Entries by Level
    console.log('Entries by Level:');
    const sortedLevels = Array.from(levelCounts.entries()).sort((a, b) => a[0].localeCompare(b[0]));
    for (const [level, count] of sortedLevels) {
      console.log(`  ${level}: ${count}`);
    }

    // Component with Most Errors
    let maxErrorComponent = '';
    let maxErrorCount = -1;
    for (const [comp, count] of componentErrorCounts.entries()) {
      if (count > maxErrorCount || (count === maxErrorCount && comp < maxErrorComponent)) {
        maxErrorCount = count;
        maxErrorComponent = comp;
      }
    }
    console.log(`Component with Most Errors: ${maxErrorComponent} (${maxErrorCount} errors)`);

    // Unique Error Messages
    console.log('Unique Error Messages:');
    const sortedMessages = Array.from(errorMessages).sort();
    for (const msg of sortedMessages) {
      console.log(`  - ${msg}`);
    }

    // Busiest Hour
    let maxHour = '';
    let maxHourCount = -1;
    for (const [hour, count] of hourCounts.entries()) {
      if (count > maxHourCount || (count === maxHourCount && hour < maxHour)) {
        maxHourCount = count;
        maxHour = hour;
      }
    }
    console.log(`Busiest Hour: ${maxHour} (${maxHourCount} entries)`);
  } catch (error) {
    // In a real scenario, we might log this, but per instructions "nothing else" to stdout.
    // If file not found, it crashes, which is expected for specific file paths.
  }
}

main();

