#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 4096
#define MAX_NAME 256
#define MAX_DEPT 256
#define MAX_EMPLOYEES 10000

typedef struct {
    char name[MAX_NAME];
    double sum_salary;
    int count;
} DeptStats;

typedef struct {
    char id[20];
    char name[MAX_NAME];
    char dept[MAX_DEPT];
    double salary;
    char start_date[20];
    char rating[20];
} Employee;

int compare_depts(const void *a, const void *b) {
    return strcmp(((DeptStats *)a)->name, ((DeptStats *)b)->name);
}

void print_comma_double(double val, int decimals, FILE *out) {
    char buf[64];
    sprintf(buf, "%.*f", decimals, val);
    char *ptr = buf;
    int len = strlen(buf);
    int dot_pos = -1;
    for (int i = 0; i < len; i++) {
        if (buf[i] == '.') {
            dot_pos = i;
            break;
        }
    }
    if (dot_pos != -1) {
        int right = 0;
        for (int i = dot_pos - 1; i >= 0; i--) {
            right++;
            if (right % 3 == 0 && right != 1) {
                ptr[i] = ',';
            }
        }
    }
    fprintf(out, "$%s", buf);
}

int main(void) {
    FILE *fp = fopen("/tmp/…/employees.csv", "r");
    if (!fp) {
        return 1;
    }

    Employee *employees = malloc(MAX_EMPLOYEES * sizeof(Employee));
    DeptStats *depts = malloc(MAX_DEPT * sizeof(DeptStats));
    int emp_count = 0;
    int dept_count = 0;
    char line[MAX_LINE];
    int total_salary = 0;
    double max_salary = -1.0;
    char max_name[MAX_NAME] = "";
    int max_idx = -1;

    if (employees == NULL || depts == NULL) {
        fclose(fp);
        return 1;
    }

    // Skip header
    if (fgets(line, MAX_LINE, fp) == NULL) goto cleanup;

    while (fgets(line, MAX_LINE, fp) != NULL) {
        char *token = strtok(line, ",");
        if (!token) continue;

        char *name_token = strtok(NULL, ",");
        char *dept_token = strtok(NULL, ",");
        char *salary_token = strtok(NULL, ",");
        char *date_token = strtok(NULL, ",");
        char *rating_token = strtok(NULL, ",");

        if (!name_token || !dept_token || !salary_token) continue;

        Employee *e = &employees[emp_count];
        strncpy(e->name, name_token, MAX_NAME - 1);
        e->name[MAX_NAME - 1] = '\0';
        strncpy(e->dept, dept_token, MAX_DEPT - 1);
        e->dept[MAX_DEPT - 1] = '\0';
        e->salary = atof(salary_token);
        strncpy(e->id, token, 19);
        e->id[19] = '\0';
        strncpy(e->start_date, date_token, 19);
        e->start_date[19] = '\0';
        strncpy(e->rating, rating_token, 19);
        e->rating[19] = '\0';

        if (e->salary > max_salary) {
            max_salary = e->salary;
            strcpy(max_name, e->name);
            max_idx = emp_count;
        }

        total_salary += (long long)e->salary;

        // Update DeptStats
        int found = 0;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(depts[i].name, e->dept) == 0) {
                depts[i].sum_salary += e->salary;
                depts[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (dept_count < MAX_DEPT) {
                strncpy(depts[dept_count].name, e->dept, MAX_NAME - 1);
                depts[dept_count].name[MAX_NAME - 1] = '\0';
                depts[dept_count].sum_salary = e->salary;
                depts[dept_count].count = 1;
                dept_count++;
            }
        }

        emp_count++;
    }

    qsort(depts, dept_count, sizeof(DeptStats), compare_depts);

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n\n");

    for (int i = 0; i < dept_count; i++) {
        double avg = depts[i].sum_salary / depts[i].count;
        printf("  Department: $");
        print_comma_double(avg, 2, stdout);
        printf("\n");
    }

    printf("\nHighest Paid: %s ($");
    print_comma_double(max_salary, 0, stdout);
    printf(")\n\n");

    printf("Departments with >2 employees:\n\n");
    for (int i = 0; i < dept_count; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }

    printf("\nTotal Budget: $");
    print_comma_double(total_salary, 0, stdout);
    printf("\n");

cleanup:
    if (employees) free(employees);
    if (depts) free(depts);
    if (fp) fclose(fp);
    return 0;
}

