public class Main {
    public static void main(String[] args) throws IOException {
        String jsonPath = "/tmp/…/graph.json";
        BufferedReader reader = new BufferedReader(new FileReader(jsonPath));
        StringBuilder contentBuilder = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            contentBuilder.append(line).append('\n');
        }
        reader.close();
        String content = contentBuilder.toString();

        // Parse nodes
        int nodesStart = content.indexOf("nodes");
        int nodesBracketStart = content.indexOf("[", nodesStart);
        int nodesBracketEnd = content.indexOf("]", nodesBracketStart);
        String nodesStr = content.substring(nodesBracketStart + 1, nodesBracketEnd);
        String[] nodesArray = nodesStr.split(",");
        List<String> nodes = new ArrayList<>();
        for (String node : nodesArray) {
            node = node.trim();
            if (!node.isEmpty()) {
                node = node.replace("\"", "");
                nodes.add(node);
            }
        }

        // Parse edges
        int edgesStart = content.indexOf("edges");
        int edgesBracketStart = content.indexOf("[", edgesStart);
        int edgesBracketEnd = content.indexOf("]", edgesBracketStart);
        String edgesStr = content.substring(edgesBracketStart + 1, edgesBracketEnd);

        List<String> edgeObjects = edgesStr.split("},");
        Map<String, List<Edge>> graph = new HashMap<>();
        for (String node : nodes) {
            graph.put(node, new ArrayList<>());
        }

        for (String obj : edgeObjects) {
            obj = obj.trim();
            if (obj.isEmpty()) continue;
            // Remove opening brace
            obj = obj.replace("{", "");
            // Split by colon
            String[] fields = obj.split(":");
            String from = null;
            String to = null;
            int weight = 0;

            // Parse fields: "from":"X","to":"Y","weight":N
            // fields[0] = "from"
            // fields[1] = "X"
            // fields[2] = ", "to"
            // fields[3] = "Y"
            // ...

            for (int i = 0; i < fields.length; i += 2) {
                String key = fields[i].trim();
                String value = fields[i + 1].trim();
                if (key.equals("from")) {
                    from = value.replace("\"", "").trim();
                } else if (key.equals("to")) {
                    to = value.replace("\"", "").trim();
                } else if (key.equals("weight")) {
                    weight = Integer.parseInt(value.replace("}", "").trim());
                }
            }

            if (from != null && to != null) {
                graph.computeIfAbsent(from, k -> new ArrayList<>()).add(new Edge(to, weight));
                graph.computeIfAbsent(to, k -> new ArrayList<>()).add(new Edge(from, weight));
            }
        }

        // Ensure A is in graph
        if (!graph.containsKey("A")) {
            graph.put("A", new ArrayList<>());
            nodes.add("A");
        }

        Map<String, Integer> distances = dijkstra(graph, "A");

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();

        List<String> sortedNodes = new ArrayList<>(nodes);
        Collections.sort(sortedNodes);

        for (String node : sortedNodes) {
            if (node.equals("A")) {
                System.out.println("A -> A: 0");
            } else {
                Integer dist = distances.getOrDefault(node, -1);
                if (dist != -1 && dist != Integer.MAX_VALUE) {
                    System.out.println("A -> " + node + ": " + dist);
                }
            }
        }
    }

    static class Edge {
        String to;
        int weight;

        Edge(String to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static Map<String, Integer> dijkstra(Map<String, List<Edge>> graph, String start) {
        Map<String, Integer> distances = new HashMap<>();
        PriorityQueue<Node> pq = new PriorityQueue<>();

        for (String node : graph.keySet()) {
            distances.put(node, Integer.MAX_VALUE);
        }
        distances.put(start, 0);
        pq.add(new Node(start, 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();
            String u = current.node;
            int d = current.distance;

            if (d > distances.get(u)) continue;

            for (Edge e : graph.get(u)) {
                int newDist = d + e.weight;
                if (newDist < distances.get(e.to)) {
                    distances.put(e.to, newDist);
                    pq.add(new Node(e.to, newDist));
                }
            }
        }

        return distances;
    }

    static class Node implements Comparable<Node> {
        String node;
        int distance;

        Node(String node, int distance) {
            this.node = node;
            this.distance = distance;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.distance, other.distance);
        }
    }
}

import * as fs from 'fs';

const inputPath = '/tmp/…/graph.json';
const data = JSON.parse(fs.readFileSync(inputPath, 'utf-8'));
const nodes = data.nodes as string[];
const edges = data.edges as Array<{from: string, to: string, weight: number}>;

// Adjacency list
const adj: Map<string, Map<string, number>> = new Map();
// Initialize adjacency list for all nodes in the JSON
for (const node of nodes) {
    adj.set(node, new Map());
}

// Populate edges (UNDIRECTED)
// Ensure adjacency keys exist even if not in nodes array (defensive)
for (const edge of edges) {
    if (!adj.has(edge.from)) adj.set(edge.from, new Map());
    if (!adj.has(edge.to)) adj.set(edge.to, new Map());
    const mapFrom = adj.get(edge.from)!;
    const mapTo = adj.get(edge.to)!;
    mapFrom.set(edge.to, edge.weight);
    mapTo.set(edge.from, edge.weight);
}

const startNode = 'A';
const dist = new Map<string, number>();
const visited = new Set<string>();

// Initialize distances for nodes in the JSON
for (const node of nodes) {
    dist.set(node, Infinity);
}
dist.set(startNode, 0);

// Dijkstra's Algorithm O(V^2)
while (dist.get(startNode) !== Infinity) {
    let u = startNode;
    let minDist = Infinity;

    // Find unvisited node with smallest distance
    for (const node of nodes) {
        if (!visited.has(node) && dist.get(node) < minDist) {
            minDist = dist.get(node)!;
            u = node;
        }
    }

    if (minDist === Infinity) break;
    visited.add(u);

    // Relax edges
    const neighbors = adj.get(u);
    if (neighbors) {
        for (const [v, weight] of neighbors.entries()) {
            // Only update if v is in our dist map (i.e., in nodes)
            if (!visited.has(v) && dist.has(v)) {
                const newDist = dist.get(u)! + weight;
                if (newDist < dist.get(v)!) {
                    dist.set(v, newDist);
                }
            }
        }
    }
}

// Output sorted alphabetically
const sortedNodes = [...new Set(nodes)].sort();

console.log('=== Shortest Paths from A ===');
console.log('');

for (const node of sortedNodes) {
    const d = dist.get(node);
    console.log(`${startNode} -> ${node}: ${d}`);
}

use std::collections::HashMap;
use std::collections::BinaryHeap;
use std::cmp::Ordering;

// For the priority queue, we need to reverse the ordering
struct Edge {
    node: String,
    distance: u64,
}

impl PartialOrd for Edge {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        other.distance.partial_cmp(&self.distance)
    }
}

fn main() {
    // Read the JSON file
    let content = std::fs::read_to_string("/tmp/…/graph.json")
        .expect("Failed to read graph.json");

    // Parse the JSON manually
    let nodes: Vec<String> = parse_nodes(&content);
    let edges: Vec<EdgeData> = parse_edges(&content);

    // Build adjacency list
    let mut adj: HashMap<String, Vec<(String, u64)>> = HashMap::new();
    for node in &nodes {
        adj.insert(node.clone(), Vec::new());
    }

    for edge in &edges {
        adj.get_mut(&edge.from).unwrap().push((edge.to.clone(), edge.weight));
        adj.get_mut(&edge.to).unwrap().push((edge.from.clone(), edge.weight));
    }

    // Dijkstra's algorithm
    let mut distances: HashMap<String, u64> = HashMap::new();
    for node in &nodes {
        distances.insert(node.clone(), u64::MAX);
    }
    distances.insert("A".to_string(), 0);

    let mut pq = BinaryHeap::new();
    pq.push(Edge { node: "A".to_string(), distance: 0 });

    while let Some(edge) = pq.pop() {
        let current_dist = edge.distance;
        let current_node = edge.node.clone();

        if current_dist > distances.get(&current_node).unwrap() {
            continue;
        }

        if let Some(neighbors) = adj.get(&current_node) {
            for (neighbor, weight) in neighbors {
                let new_dist = current_dist + weight;
                if new_dist < distances.get(neighbor).unwrap() {
                    distances.insert(neighbor.clone(), new_dist);
                    pq.push(Edge { node: neighbor.clone(), distance: new_dist });
                }
            }
        }
    }

    // Output results
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<String> = nodes.clone();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let dist = distances.get(&node).unwrap();
        println!("A -> {}: {}", node, dist);
    }
}

struct EdgeData {
    from: String,
    to: String,
    weight: u64,
}

fn parse_nodes(content: &str) -> Vec<String> {
    // Simple JSON parsing for nodes array
    let start = content.find("\"nodes\"").unwrap();
    let end = content.find("],").unwrap();
    let nodes_str = &content[start + 7..end];

    let nodes: Vec<String> = nodes_str
        .split(',')
        .map(|s| s.trim().trim_matches('"'))
        .collect();

    nodes
}

fn parse_edges(content: &str) -> Vec<EdgeData> {
    // Simple JSON parsing for edges array
    let start = content.find("\"edges\"").unwrap();
    let end = content.find("],").unwrap();
    let edges_str = &content[start + 7..end];

    let mut edges: Vec<EdgeData> = Vec::new();

    for edge_str in edges_str.split("},") {
        if edge_str.trim().is_empty() {
            continue;
        }

        let edge_str = edge_str.trim();

        // Parse from
        let from_start = edge_str.find("\"from\":").unwrap();
        let from_end = edge_str.find('"', from_start + 7).unwrap() + 1;
        let from_val = &edge_str[from_start + 7..from_end];
        let from = from_val.trim();

        // Parse to
        let to_start = edge_str.find("\"to\":").unwrap();
        let to_end = edge_str.find('"', to_start + 5).unwrap() + 1;
        let to_val = &edge_str[to_start + 5..to_end];
        let to = to_val.trim();

        // Parse weight
        let weight_start = edge_str.find("\"weight\":").unwrap();
        let weight_val = &edge_str[weight_start + 10..];
        let weight_val = weight_val.trim();
        let weight: u64 = weight_val.parse().unwrap();

        edges.push(EdgeData {
            from: from.to_string(),
            to: to.to_string(),
            weight: weight,
        });
    }

    edges
}

