fn parse_nodes(content: &str) -> Vec<String> {
    let start = content.find("\"nodes\":").unwrap();
    let end = content.find("],").unwrap();
    let nodes_str = &content[start + 9..end];

    let mut nodes = Vec::new();
    let mut chars = nodes_str.chars().peekable();

    while let Some(c) = chars.next() {
        if c == '"' {
            let mut node = String::new();
            while let Some(next_c) = chars.next() {
                if next_c == '"' {
                    break;
                }
                node.push(next_c);
            }
            nodes.push(node);
        }
    }

