fn walk_dir(base: &Path, files: &mut Vec<(String, String, usize, usize)>) -> io::Result<()> {
    if !base.exists() {
        return Ok(());
    }

    let mut entries = fs::read_dir(base)?;

    while let Some(entry) = entries.next_entry()? {
        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk_dir(&path, files)?;
        } else if path.is_file() {
            let relative_path = path.strip_prefix(base)
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_else(|_| path.to_string_lossy().to_string());

            let ext = path.extension()
                .map(|e| e.to_string_lossy().to_string())
                .unwrap_or_else(|| String::from(""));

            let (lines, chars) = count_file(&path);
            files.push((relative_path, ext, lines, chars));
        }
    }

    Ok(())
}

fn count_file(path: &Path) -> (usize, usize) {
    let content = fs::read_to_string(path).unwrap_or_else(|_| String::new());
    let lines = content.lines().count();
    let chars = content.len();
    (lines, chars)
}

