    return strcmp(fa->path, fb->path);
}

static int compareExtensions(const void *a, const void *b) {
    const ExtensionGroup *ga = (const ExtensionGroup *)a;
    const ExtensionGroup *gb = (const ExtensionGroup *)b;
    return strcmp(ga->ext, gb->ext);
}

static void getExtension(const char *path, char ext[], int max) {
    const char *dot = strrchr(path, '.');
    if (dot == NULL) {
        strcpy(ext, ".");
    } else {
        int len = (int)(dot - path);
        if (len >= max - 1) len = max - 2;
        strncpy(ext, path, len);
        ext[len] = '\0';
    }
}

static int isDirectory(const char *path) {
    struct stat st;
    return stat(path, &st) == 0 && S_ISDIR(st.st_mode);
}

static int isFile(const char *path) {
    struct stat st;
    return stat(path, &st) == 0 && S_ISREG(st.st_mode);
}

static void countLinesAndChars(const char *filepath, long *lines, long *chars) {
    FILE *fp = fopen(filepath, "r");
    if (!fp) {
        *lines = 0;
        *chars = 0;
        return;
    }

    *lines = 0;
    *chars = 0;

    char line[8192];
    while (fgets(line, sizeof(line), fp) != NULL) {
        *chars += strlen(line);
        (*lines)++;
    }

    fclose(fp);
}

static void collectFiles(const char *dir, FileInfo *files, int *count) {
    DIR *dp = opendir(dir);
    if (!dp) return;

    struct dirent *entry;
    char fullpath[MAX_PATH];

    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_name[0] == '.') continue;

        snprintf(fullpath, sizeof(fullpath), "%s/%s", dir, entry->d_name);

        if (isDirectory(fullpath)) {
            collectFiles(fullpath, files, count);
        } else if (isFile(fullpath)) {
            strncpy(files[*count].path, fullpath, MAX_PATH - 1);
            files[*count].path[MAX_PATH - 1] = '\0';
            getExtension(fullpath, files[*count].ext, MAX_EXTENSION);
            countLinesAndChars(fullpath, &files[*count].lines, &files[*count].chars);
            (*count)++;
        }
    }
    closedir(dp);
}

static void freeExtensionGroup(ExtensionGroup *group) {
    if (group->files) {
        free(group->files);
        group->files = NULL;
    }
    group->allocated = 0;
}

static void freeAllExtensions(ExtensionGroup *groups, int count) {
    for (int i = 0; i < count; i++) {
        freeExtensionGroup(&groups[i]);
    }
}

