function multiply(A: number[][], B: number[][]): number[][] {
    const rows = A.length;
    const cols = A[0].length;
    const resultRows = B.length;
    const resultCols = B[0].length;

    const C: number[][] = new Array(resultRows)
        .fill(0)
        .map(() => new Array(resultCols).fill(0));

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < resultCols; j++) {
            for (let k = 0; k < cols; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

function determinant(matrix: number[][]): number {
    const n = matrix.length;
    if (n === 1) return matrix[0][0];
    if (n === 2) return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];

    let det = 0;
    for (let i = 0; i < n; i++) {
        const minor: number[][] = [];
        for (let r = 1; r < n; r++) {
            const row: number[] = [];
            for (let c = 0; c < n; c++) {
                if (c === i) continue;
                row.push(matrix[r][c]);
            }
            minor.push(row);
        }
        const subDet = determinant(minor);
        det += matrix[0][i] * ((i % 2 === 0 ? 1 : -1) * subDet);
    }
    return det;
}

