import { readdir, readFile, stat } from 'fs/promises';
import { join, relative, extname } from 'path';

const PROJECT_TREE = '/tmp/…/project_tree';

async function walkDir(dir: string): Promise<string[]> {
    const entries = await readdir(dir, { withFileTypes: true });
    const results: string[] = [];
    for (const entry of entries) {
        const fullPath = join(dir, entry.name);
        if (entry.isSymbolicLink()) {
            continue;
        }
        if (entry.isDirectory()) {
            // Recurse into directories
            const subFiles = await walkDir(fullPath);
            results.push(...subFiles);
        } else if (entry.isFile()) {
            results.push(fullPath);
        }
    }
    return results;
}

async function analyze() {
    try {
        const files = await walkDir(PROJECT_TREE);

        const groups: Map<string, { count: number; lines: number; chars: number; files: { path: string; lines: number; chars: number }[] }> = new Map();

        for (const file of files) {
            const content = await readFile(file);

            // Snippet logic for line counting
            let lines = content.toString('utf8').split('\n');
            if (lines.length > 0 && lines[lines.length - 1] === '') {
                lines.pop();
            }
            const lineCount = lines.length;
            const charCount = content.length;

            const ext = '.' + extname(file);

            if (!groups.has(ext)) {
                groups.set(ext, { count: 0, lines: 0, chars: 0, files: [] });
            }
            const group = groups.get(ext)!;
            group.count++;
            group.lines += lineCount;
            group.chars += charCount;
            group.files.push({ path: relative(PROJECT_TREE, file), lines: lineCount, chars: charCount });
        }

        const sortedExts = Array.from(groups.keys()).sort();

        console.log('=== File Tree Analysis ===');
        console.log('');

        let totalFiles = 0;
        let totalLines = 0;
        let totalChars = 0;

        for (const ext of sortedExts) {
            const group = groups.get(ext)!;
            group.files.sort((a, b) => a.path.localeCompare(b.path));

            console.log(`Extension: ${ext}`);
            console.log(`  Files: ${group.count}`);
            console.log(`  Total Lines: ${group.lines}`);
            console.log(`  Total Characters: ${group.chars}`);
            for (const fileData of group.files) {
                console.log(`    ${fileData.path}: ${fileData.lines} lines, ${fileData.chars} chars`);
            }
            totalFiles += group.count;
            totalLines += group.lines;
            totalChars += group.chars;
        }

        console.log('');
        console.log(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);
    } catch (error) {
        // Silently handle errors to prevent outputting stack traces
        console.error(error);
    }
}

